  nintendoTokyo: { name: "Nintendo TOKYO · Shibuya PARCO", destination: "tokyo", coordinates: [35.661972, 139.698944], evidence: "Wikidata Q17992805; offizieller Nintendo-Store im PARCO", resource: "nintendo", description: "Der offizielle Nintendo-Laden im Shibuya PARCO, kein Museum und kein Freizeitpark. Schaut euch die Figuren, Spielewelten und exklusiven Souvenirs an. Zugang und Warteschlangen können organisiert werden.", suggestedTime: "45–75 Minuten", kind: "Gaming & Shopping" },
  takeshita: { name: "Takeshita Street · Harajuku", destination: "tokyo", coordinates: [35.67125, 139.70481], evidence: "Wikidata Q3179287; offizieller Takeshita-Straßenführer", resource: "takeshita", description: "Bunte Modegeschäfte, Accessoires und Süßigkeiten nahe Harajuku Station. Bummelt durch die Straße, sucht einen Crêpe oder Snack aus und geht bei Gedränge lieber in eine ruhigere Seitenstraße.", suggestedTime: "60–90 Minuten", kind: "Shopping" },
  takao: { name: "Mount Takao · Gipfel", destination: "tokyo", coordinates: [35.625278, 139.243611], evidence: "Wikidata Q1329959; Takao Tozan Wanderwege", resource: "takao", description: "Ein Berg und kein Stadtpark: feste Schuhe, Wasser und Wettercheck gehören dazu. Fahrt bei Bedarf einen Teil mit der Seilbahn und wandert nur so weit, wie es bei Hitze angenehm bleibt. Der Marker zeigt den Gipfel, nicht den Bahnhof oder den Einstieg.", suggestedTime: "Halber bis ganzer Tag", kind: "Wandern" },
